import { useSetState } from './selectors.js';
import { useChartInteractions } from '../useChartInteractions.js';
import { useXScales } from '../useXScale.js';

export const useSetResetOverlaysState = () => {
  const setState = useSetState();

  return () => {
    setState((prev) => ({
      ...prev,
      highlightedSeriesIds: prev.overlays.pinnedTooltip
        ? undefined
        : prev.highlightedSeriesIds,
      overlays: {
        ...prev.overlays,
        pinnedTooltip: false,
        visibleTooltip: false,
      },
      zoom: {
        ...prev.zoom,
        keyboardFocusMode: undefined,
        activeKeyboardMode: undefined,
      },
    }));
  };
};

export const useSetResetZoomState = () => {
  const setState = useSetState();
  const { onZoomChange } = useChartInteractions();
  const { initialScale } = useXScales();

  return () => {
    const [start, end] = initialScale.domain();
    onZoomChange && onZoomChange(start, end, 'reset');

    setState((prev) => ({
      ...prev,
      currentDomain: undefined,
      zoom: {
        ...prev.zoom,
        zoomOutEnabled: false,
        zoomInEnabled: true,
        zoomMode: 'explore',
        keyboardFocusMode: undefined,
        activeKeyboardMode: undefined,
      },
    }));
  };
};
